CREATE TABLE problems (id INTEGER PRIMARY KEY AUTOINCREMENT, author_name TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, tags_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE answers (id INTEGER PRIMARY KEY AUTOINCREMENT, problem_id INTEGER NOT NULL, author_name TEXT NOT NULL, body TEXT NOT NULL, helpful_votes INTEGER NOT NULL DEFAULT 0, unhelpful_votes INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(problem_id) REFERENCES problems(id));
CREATE TABLE votes (id INTEGER PRIMARY KEY AUTOINCREMENT, answer_id INTEGER NOT NULL, voter_key TEXT NOT NULL, value INTEGER NOT NULL CHECK(value IN (-1,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(answer_id,voter_key));
CREATE INDEX idx_answers_problem ON answers(problem_id); CREATE INDEX idx_votes_answer ON votes(answer_id);